function applyPatches(read, patches) {
  const out = {}, problems = [];
  for (const [file, find, repl] of patches) {
    const src = out[file] ?? read(file);
    if (src == null) { problems.push(file + ": file not found"); continue; }
    const n = src.split(find).length - 1;
    if (n !== 1) { problems.push(file + ": expected 1 match, found " + n + " for: " + find.split("\n")[0].slice(0, 70)); out[file] = src; continue; }
    out[file] = src.replace(find, () => repl);
  }
  return { out, problems };
}
